// {{{ Intent
// Runs once per arriving message, from the IMAP trigger. It does not move,
// delete, flag or mark anything -- the trigger is configured with
// postProcessAction=nothing precisely so that reading the inbox leaves no
// trace in it. All this node does is form an opinion and remember it; the
// schedule path of this same workflow mails the opinions out once a day.
//
// That is deliberate for the first iteration: no folders exist yet to sort
// into, and n8n's IMAP node is a trigger with no move or create-folder
// operation at all. Sorting has to be a separate, explicit decision once the
// taxonomy below has survived a week of real mail.
// }}}

// {{{ Taxonomy
// Proposed, not settled. The digest reports these as pigeonholes so the shape
// can be argued with before anything is built on it.
const BUCKETS = {
  personal: 'a person wrote to you',
  work: 'employer, colleagues, work systems',
  finance: 'banks, invoices, tax, payments',
  subscriptions: 'recurring paid services: renewals, price changes, receipts',
  newsletters: 'editorial bulk mail you opted into',
  notifications: 'automated output of a machine you own',
  shopping: 'orders, dispatch, delivery, returns',
  travel: 'bookings, tickets, check-in',
  unsolicited: 'bulk mail you did not ask for',
};

// Cheap deterministic rules run first, and win. Anything matched here never
// reaches the model: it is faster, it cannot drift between runs, and it keeps
// the machine's own mail out of the sample the model is judged on.
const RULES = [
  {bucket: 'notifications', importance: 2, test: (m) => /@tengu\.hugo-berendi\.de$/i.test(m.fromAddress)},
  {
    bucket: 'notifications',
    importance: 2,
    test: (m) => /^(no-reply|noreply|donotreply)@/i.test(m.fromAddress) && /inari|gatus|forgejo|changedetection/i.test(m.subject),
  },
  {bucket: 'work', importance: 4, test: (m) => /@datagroup\.de$/i.test(m.fromAddress)},

  // Measured, not guessed: both candidate models filed "Ihre Sendung wurde
  // zugestellt" from DHL under travel, because a parcel and a journey share a
  // noun in German. Carriers are a closed, knowable list, so this belongs in a
  // rule rather than in a longer prompt.
  {
    bucket: 'shopping',
    importance: 2,
    test: (m) => /(^|[@.])(dhl|hermes|dpd|ups|gls|deutschepost|amazon)\.[a-z.]+$/i.test(m.fromAddress),
  },
];

// The models are decent at the bucket and erratic at the number. Both rated an
// obvious crypto scam importance 5 -- "urgent" is the register such mail is
// written in, and it fools a small model. Where the bucket already settles how
// much attention is warranted, the bucket wins.
const IMPORTANCE_CLAMP = {
  unsolicited: 1,
  newsletters: 3,
  notifications: 3,
};
// }}}

// {{{ Input
const item = $input.first().json;

const headerFrom = String(item.from ?? item.From ?? '');
const fromAddress = (/<([^>]+)>/.exec(headerFrom)?.[1] ?? headerFrom).trim().toLowerCase();
const fromName = headerFrom.replace(/<[^>]*>/, '').replace(/"/g, '').trim() || fromAddress;
const subject = String(item.subject ?? item.Subject ?? '(no subject)').trim();

// The model gets a short excerpt, not the whole body: a marketing mail can be
// tens of kilobytes of table markup, and on a CPU-only server every token of
// prompt is paid for in seconds. 400 characters is also what the service's
// --ctx-size 4096 was sized around.
const body = String(item.textPlain ?? item.text ?? '')
  .replace(/https?:\/\/\S+/g, '[link]')
  .replace(/\s+/g, ' ')
  .trim();
const snippet = body.slice(0, 400);

const message = {fromAddress, fromName, subject, snippet, date: item.date ?? new Date().toISOString()};
// }}}

// {{{ Classification
// Defaults point at the dedicated 3B classifier, not the 14B next door: the
// 14B answers correctly and takes ~40 s per mail on this CPU-only box.
const CLASSIFIER_URL = $env.CLASSIFIER_URL ?? 'http://127.0.0.1:8496/v1/chat/completions';
const CLASSIFIER_MODEL = $env.CLASSIFIER_MODEL ?? 'local';
const CLASSIFIER_TIMEOUT_MS = Number($env.CLASSIFIER_TIMEOUT_MS ?? 120000);

const prompt = `You sort one email into exactly one bucket and rate how much it needs a human.

Buckets:
${Object.entries(BUCKETS)
  .map(([name, meaning]) => `- ${name}: ${meaning}`)
  .join('\n')}

importance: 5 = needs an answer or a decision soon, 4 = should be read today,
3 = worth reading, 2 = routine, glance at it, 1 = no action ever.

Answer with one JSON object and nothing else:
{"bucket":"<one bucket name>","importance":<1-5>,"why":"<at most 12 words>"}

From: ${fromName} <${fromAddress}>
Subject: ${subject}
Body: ${snippet || '(empty)'}`;

const rule = RULES.find((r) => r.test(message));

const askModel = async () => {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: CLASSIFIER_URL,
    body: {model: CLASSIFIER_MODEL, messages: [{role: 'user', content: prompt}], temperature: 0, max_tokens: 90},
    json: true,
    timeout: CLASSIFIER_TIMEOUT_MS,
  });

  const raw = response?.choices?.[0]?.message?.content ?? '';
  // Small instruct models wrap JSON in prose or a code fence often enough that
  // JSON.parse on the whole reply is not worth attempting first.
  const match = /\{[\s\S]*\}/.exec(raw);
  if (!match) throw new Error(`no JSON in reply: ${raw.slice(0, 120)}`);

  const parsed = JSON.parse(match[0]);
  const bucket = String(parsed.bucket ?? '').toLowerCase();
  // A hallucinated bucket is worse than an honest unknown, because it would
  // quietly create a pigeonhole nobody designed. The 1.7B answered "news".
  if (!Object.hasOwn(BUCKETS, bucket)) throw new Error(`unknown bucket: ${bucket}`);

  const rounded = Math.round(Number(parsed.importance));
  const bounded = Number.isFinite(rounded) ? Math.min(5, Math.max(1, rounded)) : 3;
  const ceiling = IMPORTANCE_CLAMP[bucket];

  return {
    bucket,
    importance: ceiling ? Math.min(bounded, ceiling) : bounded,
    why: String(parsed.why ?? '').slice(0, 90),
    by: 'model',
  };
};

let verdict;
if (rule) {
  verdict = {bucket: rule.bucket, importance: rule.importance, why: 'matched a deterministic rule', by: 'rule'};
} else {
  try {
    verdict = await askModel();
  } catch (error) {
    // The classifier being down must never cost the record of the mail, or the
    // digest would silently under-report the inbox.
    verdict = {bucket: 'unsorted', importance: 3, why: String(error?.message ?? error).slice(0, 90), by: 'failed'};
  }
}
// }}}

// {{{ Remember
const state = $getWorkflowStaticData('global');
state.pending ??= [];
state.pending.push({...message, ...verdict, seenAt: new Date().toISOString()});

// Static data is persisted with the workflow, so it cannot be allowed to grow
// without bound. A digest covers a day; a few hundred is generous headroom.
const CAP = 400;
if (state.pending.length > CAP) state.pending = state.pending.slice(-CAP);

return [{json: {bucket: verdict.bucket, importance: verdict.importance, by: verdict.by, subject}}];
// }}}

// {{{ Intent
// The schedule half of the organizer. Reads the opinions the classifier left
// in static data, mails them, and clears what it reported. Nothing about this
// workflow touches the mailbox: it is a proposal about how mail could be
// sorted, sent so the taxonomy can be argued with before any rule acts on it.
// }}}

const state = $getWorkflowStaticData('global');
const pending = Array.isArray(state.pending) ? state.pending : [];

const BUCKET_ORDER = [
  'personal',
  'work',
  'finance',
  'subscriptions',
  'shopping',
  'travel',
  'newsletters',
  'notifications',
  'unsolicited',
  'unsorted',
];

// Folder names are proposed here rather than in the classifier because this is
// the half a human reads: the mapping from a model's label to a real IMAP
// folder is the decision still to be made.
const FOLDER = {
  personal: 'Personal',
  work: 'Work',
  finance: 'Finance',
  subscriptions: 'Abos',
  shopping: 'Shopping',
  travel: 'Travel',
  newsletters: 'Newsletters',
  notifications: 'Automated',
  unsolicited: 'Junk',
  unsorted: '(left in place)',
};

// {{{ Roll up
const byBucket = new Map(BUCKET_ORDER.map((b) => [b, []]));
for (const mail of pending) {
  if (!byBucket.has(mail.bucket)) byBucket.set(mail.bucket, []);
  byBucket.get(mail.bucket).push(mail);
}

const populated = [...byBucket.entries()].filter(([, mails]) => mails.length > 0);
const priority = pending.filter((m) => m.importance >= 4).sort((a, b) => b.importance - a.importance);
const routine = pending.filter((m) => m.importance < 4);
const modelFailures = pending.filter((m) => m.by === 'failed');
const byModel = pending.filter((m) => m.by === 'model').length;
const byRule = pending.filter((m) => m.by === 'rule').length;
// }}}

// {{{ Rosé Pine Moon, sorting-office dress
// Same palette as every other digest here (rose-pine-moon.yaml, the scheme
// the desktops use). Duplicated because n8n Code nodes cannot import.
//
// This mail is a proposal about someone's own post, so it keeps the sorting
// office's furniture -- banded sections, rubber stamps, a torn stub -- and
// takes the palette's quieter end. Iris bands, stamps in the shared status
// colours, and no colour used for status that is not also written out.
const rp = {
  base: '#232136',
  surface: '#2a273f',
  overlay: '#393552',
  muted: '#6e6a86',
  subtle: '#908caa',
  text: '#e0def4',
  love: '#eb6f92',
  gold: '#f6c177',
  rose: '#ea9a97',
  pine: '#3e8fb0',
  foam: '#9ccfd8',
  iris: '#c4a7e7',
  highlight: '#56526e',
};

const frank = "'Courier New',Courier,monospace";
const legible = "Verdana,Geneva,'DejaVu Sans',sans-serif";

const priorityStamp = (n) =>
  n >= 5
    ? {label: 'URGENT', colour: rp.love}
    : n === 4
      ? {label: 'FIRST CLASS', colour: rp.gold}
      : n === 3
        ? {label: 'SECOND', colour: rp.foam}
        : {label: 'BULK', colour: rp.muted};

const short = (s, n) => (String(s).length > n ? `${String(s).slice(0, n - 1)}…` : String(s));
const today = new Date().toLocaleDateString('en-GB', {timeZone: 'Europe/Berlin', weekday: 'long', day: 'numeric', month: 'long'});
const postmark = new Date().toLocaleDateString('en-GB', {timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: '2-digit'});
// }}}

// {{{ Render
const band = (text, right) => `
<tr>
  <td colspan="2" style="padding:0;">
    <table role="presentation" width="100%" style="border-collapse:collapse;background:${rp.overlay};">
      <tr>
        <td style="padding:8px 30px;font-family:${frank};font-size:10px;letter-spacing:0.22em;color:${rp.iris};text-transform:uppercase;white-space:nowrap;">${text}</td>
        <td style="padding:8px 30px;font-family:${frank};font-size:9px;letter-spacing:0.1em;color:${rp.subtle};text-align:right;white-space:nowrap;">${right ?? ''}</td>
      </tr>
    </table>
  </td>
</tr>`;

const letterRow = (mail, withStamp) => {
  const s = priorityStamp(mail.importance);
  return `
<tr>
  <td style="padding:12px 12px 12px 30px;vertical-align:top;">
    <div style="font-family:${legible};font-size:13px;color:${rp.text};line-height:1.4;">${short(mail.subject, 62)}</div>
    <div style="font-family:${frank};font-size:10px;color:${rp.muted};margin-top:5px;">
      ${short(mail.fromName, 30)} &nbsp;&middot;&nbsp; ${short(mail.fromAddress, 34)}
    </div>
    ${mail.why ? `<div style="font-family:${frank};font-size:10px;color:${rp.rose};margin-top:4px;font-style:italic;">&ldquo;${mail.why}&rdquo;</div>` : ''}
  </td>
  <td style="padding:12px 30px 12px 0;text-align:right;vertical-align:top;white-space:nowrap;">
    ${
      withStamp
        ? `<div style="display:inline-block;border:1px solid ${s.colour};border-radius:3px;padding:3px 8px;">
             <span style="font-family:${frank};font-size:9px;font-weight:bold;letter-spacing:0.12em;color:${s.colour};">${s.label}</span>
           </div>`
        : ''
    }
    <div style="font-family:${frank};font-size:9px;letter-spacing:0.1em;color:${rp.subtle};margin-top:6px;">&rarr; ${FOLDER[mail.bucket] ?? mail.bucket}</div>
  </td>
</tr>
<tr><td colspan="2" style="padding:0 30px;"><div style="border-top:1px solid ${rp.overlay};"></div></td></tr>`;
};

// A bar per pigeonhole, drawn out of table cells so Outlook cannot drop it,
// scaled against the biggest bucket rather than the total: the question is
// which pile is largest, not what share of the inbox each is.
const biggest = Math.max(1, ...populated.map(([, mails]) => mails.length));

const pigeonhole = ([bucket, mails]) => {
  const pct = Math.max(3, Math.round((mails.length / biggest) * 100));
  return `
<tr>
  <td style="padding:9px 12px 3px 30px;font-family:${frank};font-size:11px;color:${rp.text};letter-spacing:0.06em;white-space:nowrap;">
    ${FOLDER[bucket] ?? bucket}<span style="color:${rp.muted};"> / ${bucket}</span>
  </td>
  <td style="padding:9px 30px 3px 0;text-align:right;font-family:${frank};font-size:11px;color:${rp.subtle};white-space:nowrap;">${mails.length}</td>
</tr>
<tr>
  <td colspan="2" style="padding:0 30px 7px 30px;">
    <table role="presentation" width="100%" style="border-collapse:collapse;table-layout:fixed;">
      <tr>
        <td width="${pct}%" style="height:3px;line-height:3px;font-size:0;background:${rp.rose};">&nbsp;</td>
        <td width="${100 - pct}%" style="height:3px;line-height:3px;font-size:0;background:${rp.overlay};">&nbsp;</td>
      </tr>
    </table>
  </td>
</tr>`;
};

const none = (text) => `
<tr><td colspan="2" style="padding:14px 30px;font-family:${legible};font-size:13px;font-style:italic;color:${rp.muted};">${text}</td></tr>`;

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:30px 14px;background:${rp.base};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;border-collapse:collapse;">
      <tr>
        <td style="background:${rp.surface};border:1px solid ${rp.overlay};border-radius:8px;overflow:hidden;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">

            <!-- franking head -->
            <tr>
              <td colspan="2" style="padding:26px 30px 20px 30px;">
                <table role="presentation" width="100%" style="border-collapse:collapse;">
                  <tr>
                    <td style="vertical-align:top;">
                      <div style="font-family:${frank};font-size:9px;letter-spacing:0.28em;color:${rp.muted};text-transform:uppercase;">inari sorting office</div>
                      <div style="font-family:${frank};font-size:25px;font-weight:bold;letter-spacing:0.06em;color:${rp.text};margin-top:11px;">THE POST</div>
                      <div style="font-family:${legible};font-size:12px;color:${rp.subtle};margin-top:9px;">${today} &middot; ${pending.length} item${pending.length === 1 ? '' : 's'} examined</div>
                    </td>
                    <td style="vertical-align:top;text-align:right;">
                      <div style="display:inline-block;border:2px solid ${rp.foam};border-radius:4px;padding:8px 11px;">
                        <div style="font-family:${frank};font-size:10px;font-weight:bold;letter-spacing:0.1em;color:${rp.foam};">NOTHING MOVED</div>
                        <div style="font-family:${frank};font-size:8px;letter-spacing:0.14em;color:${rp.foam};margin-top:4px;">${postmark}</div>
                      </div>
                    </td>
                  </tr>
                </table>
              </td>
            </tr>

            ${band('proposed pigeonholes', 'folders that do not exist yet')}
            ${populated.length ? populated.map(pigeonhole).join('\n') : none('No mail arrived since the last round.')}

            ${band('first class', `${priority.length} need${priority.length === 1 ? 's' : ''} a human`)}
            ${priority.length ? priority.map((m) => letterRow(m, true)).join('\n') : none('Nothing rated above routine.')}

            ${band('second class and bulk', `${routine.length} item${routine.length === 1 ? '' : 's'}`)}
            ${routine.length ? routine.slice(0, 18).map((m) => letterRow(m, false)).join('\n') : none('Nothing routine either.')}
            ${routine.length > 18 ? none(`… and ${routine.length - 18} further items not listed.`) : ''}

            ${modelFailures.length ? band('could not be read', `${modelFailures.length} classifier failure${modelFailures.length === 1 ? '' : 's'}`) : ''}
            ${modelFailures.length ? modelFailures.map((m) => letterRow(m, false)).join('\n') : ''}

            <!-- torn stub -->
            <tr><td colspan="2" style="padding:0;font-family:${frank};font-size:11px;line-height:11px;color:${rp.overlay};letter-spacing:3px;background:${rp.surface};">
              ${'●'.repeat(58)}
            </td></tr>
            <tr>
              <td colspan="2" style="padding:16px 30px 24px 30px;background:${rp.base};">
                <table role="presentation" width="100%" style="border-collapse:collapse;">
                  <tr>
                    <td style="font-family:${frank};font-size:9px;letter-spacing:0.12em;color:${rp.subtle};">
                      by rule: ${byRule} &nbsp;&middot;&nbsp; by model: ${byModel} &nbsp;&middot;&nbsp; failed: ${modelFailures.length}
                    </td>
                    <td style="font-family:${frank};font-size:9px;letter-spacing:0.12em;color:${rp.muted};text-align:right;">no. ${postmark.replace(/\//g, '')}</td>
                  </tr>
                  <tr>
                    <td colspan="2" style="padding-top:11px;font-family:${legible};font-size:11px;color:${rp.subtle};line-height:1.6;">
                      Nothing in your mailbox was moved, flagged or marked read. Reply with the
                      pigeonholes you actually want and sorting can be built on this.
                    </td>
                  </tr>
                </table>
              </td>
            </tr>

          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
// }}}

// Only clear what this digest reported: anything the classifier appends while
// this node runs has to survive to the next round.
const reported = pending.length;
state.pending = (Array.isArray(state.pending) ? state.pending : []).slice(reported);

const subject = pending.length
  ? `The post · ${pending.length} examined, ${priority.length} first class`
  : 'The post · nothing arrived';

return [{json: {subject, html, reported}}];
